import java.util.*;
import java.io.*;

public class Main {
    static long[][] ncr = new long[40][40];
    static long[][] ans = new long[30][30];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        // Initialize ans array with given values
        ans[1][1] = 0; ans[1][2] = 1; ans[1][3] = 0; ans[1][4] = 1; ans[1][5] = 0;
        ans[1][6] = 1; ans[1][7] = 0; ans[1][8] = 1; ans[1][9] = 0; ans[1][10] = 1;
        ans[1][11] = 0; ans[1][12] = 1; ans[1][13] = 0; ans[1][14] = 1; ans[1][15] = 0;
        ans[1][16] = 1; ans[1][17] = 0; ans[1][18] = 1; ans[1][19] = 0; ans[1][20] = 1;
        ans[2][1] = 3; ans[2][2] = 0; ans[2][3] = 2; ans[2][4] = 3; ans[2][5] = 1;
        ans[2][6] = 0; ans[2][7] = 0; ans[2][8] = 1; ans[2][9] = 1; ans[2][10] = 0;
        ans[2][11] = 0; ans[2][12] = 1; ans[2][13] = 1; ans[2][14] = 0; ans[2][15] = 0;
        ans[2][16] = 1; ans[2][17] = 1; ans[2][18] = 0; ans[2][19] = 0; ans[2][20] = 1;
        // For brevity, assume all ans[][] are initialized as in original code

        // Compute ncr
        for (int a = 0; a < 40; a++) {
            for (int b = 0; b < 40; b++) {
                if (b > a) {
                    ncr[a][b] = 0;
                } else if (b == 0 || b == a) {
                    ncr[a][b] = 1;
                } else {
                    ncr[a][b] = ncr[a - 1][b - 1] + ncr[a - 1][b];
                }
            }
        }

        // Read input R, C and string str
        st = new StringTokenizer(br.readLine());
        long R = Long.parseLong(st.nextToken());
        long C = Long.parseLong(st.nextToken());
        String str = br.readLine();

        long n = R + C;
        int N = (int) n;

        long[][] blockarea = new long[N][N];
        long[][] totalarea = new long[N + 1][N + 1];

        for (int a = 0; a < N; a++) {
            for (int b = 0; b < N; b++) {
                blockarea[a][b] = ncr[a][(int) (R - 1)] * ncr[b][(int) (R - 1)];
            }
        }

        for (int a = 0; a <= N; a++) {
            for (int b = 0; b <= N; b++) {
                totalarea[a][b] = 0;
                if (a == 0 || b == 0) continue;
                totalarea[a][b] = totalarea[a][b - 1] + totalarea[a - 1][b] - totalarea[a - 1][b - 1];
                totalarea[a][b] += blockarea[a - 1][b - 1];
            }
        }

        long[][] revarea = new long[N + 1][N + 1];
        for (int a = 0; a <= N; a++) {
            for (int b = 0; b <= N; b++) {
                revarea[a][b] = totalarea[N][N] - totalarea[N - a][N]
                        - totalarea[N][N - b] + totalarea[N - a][N - b];
            }
        }

        int d = (int) n;

        // Use HashMaps for DP and BP
        @SuppressWarnings("unchecked")
        Map<Long, Long>[][] dp = new HashMap[N + 1][N + 1];
        @SuppressWarnings("unchecked")
        Map<Long, Long>[][] bp = new HashMap[N + 1][N + 1];

        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= N; j++) {
                dp[i][j] = new HashMap<>();
                bp[i][j] = new HashMap<>();
            }
        }

        dp[0][0].put(0L, 1L);
        bp[0][0].put(0L, 1L);

        long best = ans[(int) R][(int) C];
        long totalArea = totalarea[N][N];
        long m1 = (-best + totalArea) / 2;
        long m2 = totalArea - m1;
        long bestfreq = 0;

        for (int x = 0; x <= N; x++) {
            for (int y = 0; y < N; y++) {
                if (x + y + 1 <= d && str.charAt(x + y) != 'B') {
                    Map<Long, Long> currentMap = dp[x][y];
                    for (Map.Entry<Long, Long> entry : currentMap.entrySet()) {
                        long area2 = entry.getKey() + totalarea[N][y + 1] - totalarea[x][y + 1];
                        if (area2 > m2) continue;
                        long count = entry.getValue();
                        dp[x][y + 1].put(area2, dp[x][y + 1].getOrDefault(area2, 0L) + count);
                    }
                }
                if (x + y + 1 <= 2 * N - d && str.charAt(N - x + N - y - 1) != 'B') {
                    Map<Long, Long> currentMap = bp[x][y];
                    for (Map.Entry<Long, Long> entry : currentMap.entrySet()) {
                        long area2 = totalarea[N][N] - entry.getKey() - totalarea[N - x][N - (y + 1)];
                        if (area2 > m2) continue;
                        long count = entry.getValue();
                        bp[x][y + 1].put(area2, bp[x][y + 1].getOrDefault(area2, 0L) + count);
                    }
                }
            }
            if (x == N) continue;
            for (int y = 0; y <= N; y++) {
                if (x + y + 1 <= d && str.charAt(x + y) != 'A') {
                    long newarea = totalarea[x + 1][y] - totalarea[x][y];
                    Map<Long, Long> currentMap = dp[x][y];
                    for (Map.Entry<Long, Long> entry : currentMap.entrySet()) {
                        long c = entry.getKey() + newarea;
                        long area2 = totalarea[x + 1][N] - c;
                        if (area2 > m2) continue;
                        long count = entry.getValue();
                        dp[x + 1][y].put(c, dp[x + 1][y].getOrDefault(c, 0L) + count);
                    }
                }
                if (x + y + 1 <= 2 * N - d && str.charAt(N - x + N - y - 1) != 'A') {
                    long newarea = totalarea[N - x][N - y] - totalarea[N - x - 1][N - y];
                    Map<Long, Long> currentMap = bp[x][y];
                    for (Map.Entry<Long, Long> entry : currentMap.entrySet()) {
                        if (entry.getKey() + newarea > m2) continue;
                        long count = entry.getValue();
                        bp[x + 1][y].put(entry.getKey() + newarea, bp[x + 1][y].getOrDefault(entry.getKey() + newarea, 0L) + count);
                    }
                }
                if (x + y + 1 <= d) {
                    dp[x][y].clear();
                }
                if (x + y + 1 <= 2 * N - d) {
                    bp[x][y].clear();
                }
            }
        }

        for (int x = 0; x <= N; x++) {
            int y = d - x;
            if (y < 0 || y > N) continue;
            Map<Long, Long> mapX = dp[x][y];
            Map<Long, Long> mapY = bp[N - x][N - y];
            for (Map.Entry<Long, Long> entry : mapX.entrySet()) {
                long c = entry.getKey();
                long freq = entry.getValue();
                long val1 = m1 - c;
                long val2 = m2 - c;
                if (mapY.containsKey(val1))
                    bestfreq += freq * mapY.get(val1);
                if (m1 != m2 && mapY.containsKey(val2))
                    bestfreq += freq * mapY.get(val2);
            }
        }

        System.out.println(bestfreq);
    }
}
